const fresh=()=>({title:'마지막 열차',synopsis:'매일 같은 역에서 마지막 열차를 기다리는 사진가 윤. 어느 날, 10년 전 자신이 보낸 엽서를 든 여행자를 만난다. 두 사람은 사라져 가는 작은 역을 사진에 담으며, 미뤄 두었던 각자의 여행을 시작한다.',duration:300,analyzed:false,storyApproved:false,timelineApproved:false,imageApproved:false,candidate:0,imageProvider:'Grok Imagine',mode:'혼합',orchestration:'역할 고정',primary:'OpenAI · 구독 모델',tab:'시놉시스',settingsTab:'계정·모델',selected:0,statuses:Array(20).fill('waiting'),retry:false,connections:[],auth:{},pipeline:['Ollama · 로컬 모델'],enhanced:false,imageGenerated:false,candidates:[],candidateCount:1,candidateMode:'같은 컨셉',variationAxis:'조명',enhanceModel:'Ollama · 로컬 모델',workflowGraphs:{}});
