function inputError(selector,message){const field=$(selector);if(!field?.setAttribute)return toast(message);field.setAttribute('aria-invalid','true');const id=(field.id||'validation-field')+'-error';document.getElementById(id)?.remove();const note=document.createElement('p');note.id=id;note.className='field-error';note.setAttribute('role','alert');note.textContent=message;field.setAttribute('aria-describedby',id);field.insertAdjacentElement('afterend',note);field.focus({preventScroll:false});}
if(projectStore.shared.enhancementInstruction===undefined){state.enhancementInstruction=state.enhancementInstruction||referenceLibrary.draft.instruction||'';projectStore.shared.enhancementInstruction=state.enhancementInstruction;}
