function resolveSelectedAssets(){const selected=state.comfySelectedLoras||[];const issues=[];if(!state.comfyScanned||!demoComfyModels.includes(state.comfySelectedModel))issues.push('서버 목록에서 사용할 모델을 선택해 주세요.');const loras=selected.map(id=>{const item=demoComfyLoras.find(l=>l.id===id);if(!item?.source){issues.push(id+' · 일치하는 배포 버전과 권장값을 확인하지 못했어요.');return {name:id,strength:null,source:null};}if(item.model!==state.comfySelectedModel)issues.push(id+' · 선택 모델과 호환되지 않아요.');return {name:id,strength:item.strength,source:item.source};});state.comfyRecommendations={model:state.comfySelectedModel,loras,issues,status:issues.length?'review_required':'ready',reason:'사용자 선택 자산의 호환성과 출처별 권장값을 확인한 데모',demo:true};return state.comfyRecommendations;}
function recommendationSummary(){const r=state.comfyRecommendations;if(!r)return '';return `<div class="note"><strong>${r.status==='ready'?'권장 설정 준비됨':'확인 필요'} · 데모</strong>${r.issues.map(i=>`<p class="field-error">${esc(i)}</p>`).join('')}${r.loras.map(l=>`<p>${esc(l.name)} · ${l.strength===null?'강도 미확정':'적용 강도 '+l.strength}<small>${esc(l.source||'출처 미확인')} · 실제 조회 아님</small></p>`).join('')}<small>목업의 예시 값입니다. 실제 적용 전 정확한 파일·버전과 권장 범위를 확인합니다.</small></div>`}
